/**
 * The Signpost (where the road leaves the camp) at the five valley levels of `docs/design/art-levels.md`,
 * and the Market (built once, keeps its art). Every road level is drawn on one 64x56 canvas with the post's
 * foot on the same row; the road is short and heads right from the foot. Materials come from `valley-tiers.ts`.
 * Main palette is night with the lantern's (or crystal's) light lying on the ground, `alts.day` recolours the
 * same pixels with the lanterns unlit. Generated by a script, then kept as data.
 */
import type { SpriteDef } from '../sprite-data';
import { INK, TIERS, tierPalette } from './valley-tiers';
import { VALLEY_GLOW_CONCEPTS } from './valley-glow';
import type { ConceptSet } from './index';

type Parts = { palette: Record<string, string>; day: Record<string, string> };

/** Material palettes plus the level's own keys (ink, shadow, ground, light) merged into a sprite and its day alt. */
function level(
  parts: readonly Parts[],
  own: { night: Record<string, string>; day: Record<string, string> },
  rows: string[],
): { sprite: SpriteDef; day: Record<string, string> } {
  const palette: Record<string, string> = {};
  const day: Record<string, string> = {};
  for (const part of parts) {
    Object.assign(palette, part.palette);
    Object.assign(day, part.day);
  }
  Object.assign(palette, own.night);
  Object.assign(day, own.day);
  return { sprite: { palette, rows }, day };
}

